<script>
'use strict';
/* ================= GALAGA CLONE =================
   Native resolution 224x288 (arcade 3:4), fixed 60Hz timestep.
   Sections: setup, audio, sprites, helpers, state, formation,
   enemies, player, bullets, collisions, challenging stage,
   update, render, loop.
=================================================== */

/* ---------- canvas / scaling ---------- */
const W=224,H=288;
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
canvas.width=W;canvas.height=H;ctx.imageSmoothingEnabled=false;
function fit(){const s=Math.max(1,Math.floor(Math.min(innerWidth/W,innerHeight/H)));
  canvas.style.width=(W*s)+'px';canvas.style.height=(H*s)+'px';}
addEventListener('resize',fit);fit();

/* ---------- audio (Web Audio, synthesized) ---------- */
let AC=null,master=null,beamNode=null,noiseBuf=null;
function audioInit(){
  if(!AC){AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain();master.gain.value=0.3;master.connect(AC.destination);}
  if(AC.state==='suspended')AC.resume();
}
let muted=false;
function setMute(m){muted=m;if(master)master.gain.value=m?0:0.3;}
function tone(f0,f1,dur,type,vol,delay){
  if(!AC)return;delay=delay||0;const t=AC.currentTime+delay;
  const o=AC.createOscillator(),g=AC.createGain();o.type=type;
  o.frequency.setValueAtTime(Math.max(1,f0),t);
  o.frequency.exponentialRampToValueAtTime(Math.max(1,f1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+0.03);
}
function getNoise(){
  if(!noiseBuf){noiseBuf=AC.createBuffer(1,AC.sampleRate,AC.sampleRate);
    const d=noiseBuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;}
  return noiseBuf;
}
function noiseBurst(dur,vol,f1,f2){
  if(!AC)return;const t=AC.currentTime;
  const s=AC.createBufferSource();s.buffer=getNoise();s.loop=true;
  const fl=AC.createBiquadFilter();fl.type='lowpass';
  fl.frequency.setValueAtTime(f1,t);fl.frequency.exponentialRampToValueAtTime(f2,t+dur);
  const g=AC.createGain();g.gain.setValueAtTime(vol,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(fl);fl.connect(g);g.connect(master);s.start(t);s.stop(t+dur+0.02);
}
const sfx={
  shot(){tone(1050,260,0.07,'square',0.12);},
  enemyDie(){noiseBurst(0.18,0.3,2400,200);tone(320,80,0.18,'triangle',0.15);},
  bigDie(){noiseBurst(0.3,0.35,2400,120);tone(260,60,0.3,'sawtooth',0.18);},
  bossHit(){tone(760,420,0.09,'square',0.2);},
  playerDie(){noiseBurst(0.6,0.45,1800,80);tone(220,40,0.6,'sawtooth',0.25);},
  capture(){tone(700,90,0.9,'sawtooth',0.2);},
  dock(){[520,660,880,1180].forEach((f,i)=>tone(f,f,0.08,'square',0.15,i*0.06));},
  wave(){tone(1150,1150,0.07,'square',0.15);tone(1150,1150,0.07,'square',0.15,0.12);},
  bonus(){[660,880,1320,1760].forEach((f,i)=>tone(f,f,0.1,'triangle',0.2,i*0.1));},
  jingle(){ // short stage-start jingle
    const n=[[392,0],[523,0.12],[659,0.24],[784,0.36],[659,0.52],[784,0.64],[1046,0.80]];
    n.forEach(p=>tone(p[0],p[0],0.11,'square',0.16,p[1]));
  }
};
function beamStart(){
  if(!AC||beamNode)return;
  const o=AC.createOscillator(),g=AC.createGain(),l=AC.createOscillator(),lg=AC.createGain();
  o.type='sawtooth';o.frequency.value=170;l.type='sine';l.frequency.value=12;lg.gain.value=70;
  l.connect(lg);lg.connect(o.frequency);g.gain.value=0.1;o.connect(g);g.connect(master);
  o.start();l.start();beamNode={o,l};
}
function beamStop(){if(beamNode){try{beamNode.o.stop();beamNode.l.stop();}catch(e){}beamNode=null;}}

/* ---------- pixel sprites (baked to offscreen canvases) ---------- */
function bake(rows,pal){
  const h=rows.length,w=rows[0].length,c=document.createElement('canvas');
  c.width=w;c.height=h;const g=c.getContext('2d');
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){const ch=rows[y][x];
    if(ch!=='.'){g.fillStyle=pal[ch];g.fillRect(x,y,1,1);}}
  return c;
}
const PAL={
  player:{W:'#ffffff',B:'#2a7bff'},
  captured:{W:'#ff5050',B:'#ffd0d0'},
  zako:{Y:'#ffd820',B:'#2a5cff'},
  goei:{R:'#ff3030',B:'#2a5cff'},
  bossG:{G:'#22cc22',B:'#e8e8e8'},
  bossP:{G:'#3030e0',B:'#c070ff'}
};
const SPR={};
SPR.player=bake([
"......W......",
"......W......",
".....WWW.....",
".....WBW.....",
"....WWBWW....",
".W..WWBWW..W.",
".WW.WWBWW.WW.",
"WWWWWWBWWWWWW",
".WWWW.B.WWWW.",
"..WWWW.WWWW..",
"...W.....W..."],PAL.player);
SPR.captured=bake([
"......W......",
"......W......",
".....WWW.....",
".....WBW.....",
"....WWBWW....",
".W..WWBWW..W.",
".WW.WWBWW.WW.",
"WWWWWWBWWWWWW",
".WWWW.B.WWWW.",
"..WWWW.WWWW..",
"...W.....W..."],PAL.captured);
SPR.zako1=bake([
".....YYY.....",
".....BBB.....",
"YYY..BBB..YYY",
"YYYY.BBB.YYYY",
".YYYBBBBBYYY.",
"..YYBBBBBYY..",
"...YBBBBBY...",
"....BBBBB....",
".....BBB.....",
"....B...B...."],PAL.zako);
SPR.zako2=bake([
".....YYY.....",
".....BBB.....",
".Y...BBB...Y.",
".YY..BBB..YY.",
".YYYBBBBBYYY.",
"..YYBBBBBYY..",
"...YBBBBBY...",
"....BBBBB....",
".....BBB.....",
"....B...B...."],PAL.zako);
SPR.goei1=bake([
"RR.........RR",
"RRR..RRR..RRR",
".RRRRBBBRRRR.",
".RRRBBBBBRRR.",
"..RRBBBBBRR..",
"...BBBBBBB...",
"....B.B.B....",
"...B..B..B..."],PAL.goei);
SPR.goei2=bake([
".............",
".....RRR.....",
"R...RBBBR...R",
"RR.RRBBBRR.RR",
".RRRBBBBBRRR.",
"...BBBBBBB...",
"....B.B.B....",
"............."],PAL.goei);
SPR.boss1=bake([
"..G.........G..",
"..G.........G..",
"..GG.......GG..",
"...GG.....GG...",
"....G.GGG.G....",
"....GGGGGGG....",
".GGGGBBBBBGGGG.",
"GGGGGBBBBBGGGGG",
".GGGGBBBBBGGGG.",
"..GGGBBBBBGGG..",
"...G..BBB..G...",
"......BBB......",
".....B...B....."],PAL.bossG);
SPR.boss2=bake([
"..G.........G..",
"..G.........G..",
"..GG.......GG..",
"...GG.....GG...",
"....G.GGG.G....",
"....GGGGGGG....",
".GGGGBBBBBGGGG.",
"GGGGGBBBBBGGGGG",
".GGGGBBBBBGGGG.",
"..GGGBBBBBGGG..",
"...G..BBB..G...",
"......BBB......",
".....B...B....."],PAL.bossP);
SPR.bullet=bake(["Y","Y","Y","Y","Y","Y"],{Y:'#ffd820'});
SPR.pbullet=bake(["W","W","W","W","W","W"],{W:'#d0f0ff'});
SPR.flag5=bake(["RRR.","R.R.","R..R","....","..P.","..P.","..P.","..P."],{R:'#ff3030',P:'#ffffff'});
SPR.flag1=bake(["BBB.","B.B.","B..B","....","..P.","..P.","..P.","..P."],{B:'#2a9bff',P:'#ffffff'});

/* ---------- tiny math helpers ---------- */
const rand=Math.random, rnd=(a,b)=>a+rand()*(b-a), ri=(a,b)=>Math.floor(rnd(a,b+1));
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
function cubicBez(p,t){const u=1-t;
  return{x:u*u*u*p[0].x+3*u*u*t*p[1].x+3*u*t*t*p[2].x+t*t*t*p[3].x,
         y:u*u*u*p[0].y+3*u*u*t*p[1].y+3*u*t*t*p[2].y+t*t*t*p[3].y};}
function sampleBez(p,n){const a=[];for(let i=0;i<=n;i++)a.push(cubicBez(p,i/n));return a;}
function sampleLoop(cx,cy,r,a0,a1,n){const a=[];for(let i=0;i<=n;i++){const a2=a0+(a1-a0)*i/n;
  a.push({x:cx+r*Math.cos(a2),y:cy+r*Math.sin(a2)});}return a;}
function pathLen(pts){let L=0;for(let i=1;i<pts.length;i++)L+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);return L;}
function ptAt(pts,d){let acc=0;
  for(let i=1;i<pts.length;i++){const seg=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);
    if(acc+seg>=d){const t=(d-acc)/seg;
      return{x:pts[i-1].x+(pts[i].x-pts[i-1].x)*t,y:pts[i-1].y+(pts[i].y-pts[i-1].y)*t};}
    acc+=seg;}
  return pts[pts.length-1];}
function pointOnPath(e,path,d){
  const p=ptAt(path,d);const q=ptAt(path,d+3);
  e.x=p.x;e.y=p.y;
  const dx=q.x-p.x,dy=q.y-p.y;
  if(dx*dx+dy*dy>0.2)e.ang=Math.atan2(dy,dx);
}

/* ---------- game state ---------- */
const G={
  mode:'attract', frame:0, paused:false,
  stage:1, score:0,
  hi:parseInt(localStorage.getItem('galagaHi')||'0',10)||0,
  lives:2, dual:false,
  enemies:[], pshots:[], eshots:[], fx:[],
  player:{x:112,alive:false,respawn:0},
  captured:null,          // captured fighter entity (held by boss)
  diveTimer:420,
  shotsFired:0, shotsHit:0, nextExtra:20000,
  banner:null, msg:[], chal:null,
  attractT:0
};
function saveHi(){if(G.score>G.hi){G.hi=G.score;localStorage.setItem('galagaHi',''+G.hi);}}
function addMsg(t,x,y,life,col){G.msg.push({t,x,y,life,max:life,col:col||'#fff'});}
function addScore(n,x,y){G.score+=n;addMsg(''+n,x,y-8,40,'#ffd820');
  if(G.score>=G.nextExtra){G.lives++;G.nextExtra+=70000;sfx.bonus();addMsg('EXTRA SHIP!',112,150,90,'#22ff22');}
  saveHi();}

/* ---------- formation geometry ---------- */
const FORM={ox:0,oy:0,t:0,full:false};
function slotPos(col,row){return{x:112+(col-4.5)*16+FORM.ox,y:36+row*16+FORM.oy};}
function formationComplete(){return G.enemies.every(e=>e.st==='formation'||e.st==='captive');}
function updateFormation(){
  FORM.t++;
  FORM.full=formationComplete();
  const amp=FORM.full?4:7, sw=FORM.full?0.009:0.02;
  FORM.ox=Math.sin(FORM.t*sw)*amp;
  FORM.oy=FORM.full?Math.sin(FORM.t*0.03)*2:0;
}

/* ---------- enemies ---------- */
function makeEnemy(type,col,row){
  return{type,col,row,x:-40,y:-40,ang:Math.PI/2,st:'enter',path:null,d:0,spd:2.2,
    bez:null,t:0,seg:0,hp:type==='boss'?2:1,flash:0,esc:null,fire:0,
    flap:0,flapT:ri(0,15),hostile:false,beamT:0,dir:1,pts:0};
}
function setDivePath(e){
  const s=slotPos(e.col,e.row);
  const sgn=e.x<112?-1:1;
  const ex=clamp(e.x+sgn*rnd(20,90),16,W-16);
  e.path=[
    sampleBez([{x:s.x,y:s.y},{x:s.x+sgn*rnd(10,30),y:s.y+rnd(10,25)},
      {x:clamp(ex-sgn*rnd(20,50),10,W-10),y:s.y+rnd(30,55)},{x:ex,y:s.y+70}],14),
    sampleBez([{x:ex,y:s.y+70},{x:ex-sgn*rnd(10,40),y:s.y+100},
      {x:ex+sgn*rnd(10,40),y:s.y+135},{x:clamp(ex+sgn*rnd(0,50),10,W-10),y:H+30}],20)
  ];
  e.seg=0;e.d=0;e.st='dive';
  e.fire=e.type==='boss'?ri(20,45):ri(35,90);
}
function setReturnPath(e){
  const s=slotPos(e.col,e.row);
  e.bez=[{x:clamp(s.x+rnd(-45,45),8,W-8),y:-18},
         {x:s.x+rnd(-55,55),y:rnd(20,60)},{x:s.x+rnd(-25,25),y:s.y-30},{x:s.x,y:s.y}];
  e.t=0;e.st='return';
}
function setBeamPath(e){
  const s=slotPos(e.col,e.row);
  const tx=clamp(G.player.x+rnd(-20,20),30,W-30);
  e.path=[sampleBez([{x:s.x,y:s.y},{x:s.x+rnd(-30,30),y:s.y+50},{x:tx+rnd(-25,25),y:95},{x:tx,y:112}],26)];
  e.seg=0;e.d=0;e.st='dive';e.fire=1000;e.beamT=0;
}
function setHostilePath(e){ // captive turned hostile: continuous dives
  const s=slotPos(e.col,e.row);
  const sgn=rand()<0.5?-1:1;
  e.path=[sampleBez([{x:s.x,y:s.y},{x:s.x+sgn*rnd(20,50),y:s.y+40},
    {x:rnd(20,W-20),y:H*0.6},{x:rnd(20,W-20),y:H+25}],28)];
  e.seg=0;e.d=0;e.st='dive';e.fire=ri(20,50);
}
function enterFormation(e){
  e.st='formation';
  if(e.type==='boss'&&G.captured&&G.captured.boss===e){
    G.captured.st='captive';
    if(G.captured.held){G.captured.held=false;G.lives--;startRespawn();}
  }
}
function startRespawn(){
  const alive=G.lives>0||G.dual;
  if(!alive){endGame();return;}
  G.player.respawn=110;
}
function endGame(){
  beamStop();
  G.banner={t:'GAME OVER',t0:G.frame,dur:180,next:'results'};
  G.mode='gameover';
}
function killEnemy(e){
  e.dead=true;
  if(e.type==='boss'){
    sfx.bigDie();
    let pts=150;
    if(e.st==='dive'||e.st==='beam'){
      let esc=0;if(e.esc)e.esc.forEach(o=>{if(!o.dead)esc++;});
      pts=[400,800,1600][esc];
    }
    addScore(pts,e.x,e.y);
    // free or release captive
    if(G.captured&&G.captured.boss===e){
      const c=G.captured;
      if((e.st==='dive'||e.st==='beam')&&G.lives>0&&!G.dual&&G.player.alive){
        c.st='freed';c.boss=null;c.vy=1.5;G.captured=null;
      }else if(c.st!=='freed'){
        c.st='hostile';c.boss=null;c.hostile=true;c.pts=100;G.captured=null;
        setHostilePath(c);
      }
    }
  }else{
    sfx.enemyDie();
    const diving=(e.st==='dive'||e.st==='beam');
    const pts=e.type==='goei'?(diving?160:80):(diving?100:50);
    addScore(pts,e.x,e.y);
  }
  G.fx.push({kind:'boom',x:e.x,y:e.y,t:0,big:e.type==='boss'});
}
function enemyFire(e){
  const px=G.player.x,py=H-24;
  const dx=px-e.x,dy=py-e.y,l=Math.hypot(dx,dy)||1;
  const sp=1.5+0.05*G.stage;
  G.eshots.push({x:e.x,y:e.y+6,vx:dx/l*sp,vy:dy/l*sp});
}
function updateEnemy(e){
  e.flapT++;if(e.flapT>11){e.flapT=0;e.flap^=1;}
  if(e.flash)e.flash--;
  if(e.st==='entry'){
    if(e.delay>0){e.delay--;return;}
    e.d+=e.spd;
    if(e.d>=e.len){e.st='toSlot';e.bez=[{x:e.x,y:e.y},
      {x:e.x+(e.x<112?-30:30),y:e.y-25},{x:e.x,y:e.y-30},slotPos(e.col,e.row)];e.t=0;}
    else pointOnPath(e,e.path,e.d);
    if(G.frame%90===0&&rand()<0.35)enemyFire(e); // may fire while entering
  }else if(e.st==='toSlot'){
    e.t+=0.04;const p=cubicBez(e.bez,Math.min(1,e.t));e.x=p.x;e.y=p.y;
    if(e.t>=1)enterFormation(e);
  }else if(e.st==='formation'){
    const s=slotPos(e.col,e.row);e.x=s.x;e.y=s.y;e.dir=1;
  }else if(e.st==='captive'){
    const s=slotPos(e.boss.col,e.boss.row);e.x=s.x;e.y=s.y-16;e.dir=1;
    if(e.boss.st==='dive'||e.boss.st==='beam'){
      if(e.fire--<=0){e.fire=ri(40,90);enemyFire(e);}
    }
  }else if(e.st==='dive'){
    e.d+=2.2+0.05*G.stage;
    if(e.seg>=e.path.length){ // exited bottom: re-enter from top, return to slot
      e.x=clamp(e.x+rnd(-30,30),10,W-10);e.y=-14;e.dir=1;setReturnPath(e);return;}
    const seg=e.path[e.seg];
    if(e.d>=pathLen(seg)){e.seg++;e.d=0;return;}
    pointOnPath(e,seg,e.d);
    if(e.esc)e.esc.forEach((o,i)=>{if(o.st==='formation'){o.st='escort';o.lead=e;o.off=(i+1)*18;}});
    if(e.fire--<=0){e.fire=ri(40,100);enemyFire(e);}
    if(e.y>H+20){e.seg++;e.d=0;}
  }else if(e.st==='escort'){
    const t=e.lead.ang+Math.PI/2;
    const tx=e.lead.x+Math.cos(t)*e.off,ty=e.lead.y+Math.sin(t)*e.off;
    e.x+=(tx-e.x)*0.2;e.y+=(ty-e.y)*0.2;e.dir=Math.cos(t)>=0?1:-1;
    if(e.fire===undefined)e.fire=ri(60,120);
    if(e.fire--<=0){e.fire=ri(60,140);enemyFire(e);}
  }else if(e.st==='beam'){
    e.x+=Math.sin(G.frame*0.06)*1.2; // hover wobble
    if(e.esc)e.esc.forEach((o,i)=>{if(o.st==='formation'){o.st='escort';o.lead=e;o.off=(i+1)*18;}});
    e.beamT++;
    if(e.beamT===1)beamStart();
    if(e.beamT>200){beamStop();e.st='beamUp';e.vy=-2.4;}
  }else if(e.st==='beamUp'){
    e.y+=e.vy;
    if(e.y<-16)setReturnPath(e);
  }else if(e.st==='return'){
    e.t+=0.028;const p=cubicBez(e.bez,Math.min(1,e.t));e.x=p.x;e.y=p.y;e.dir=1;
    if(e.t>=1)enterFormation(e);
  }else if(e.st==='freed'){ // freed captive flying down to dock
    e.y+=2;e.x+=(G.player.x-e.x)*0.05;
    if(e.y>=H-24){
      e.dead=true;G.captured=null;
      if(G.player.alive){G.dual=true;sfx.dock();addMsg('DUAL FIGHTER!',112,150,90,'#22ff22');}
    }
  }else if(e.st==='hostile'){
    updateEnemy(Object.assign(e,{_h:1})); // reuse dive logic below
  }
}
// hostile captive re-dive handling (kept separate to avoid recursion)
function updateHostile(e){
  e.d+=2.4;
  const seg=e.path[0];
  if(e.d>=pathLen(seg)){e.d=0;const s=slotPos(e.col,e.row);
    e.path=[sampleBez([{x:e.col%2?W+16:-16},{x:0,y:0},{x:0,y:0},{x:0,y:0}],1)]; // placeholder replaced below
    // re-enter from top and dive again
    e.path=[sampleBez([{x:clamp(s.x+rnd(-40,40),10,W-10),y:-16},
      {x:rnd(20,W-20),y:H*0.3},{x:rnd(20,W-20),y:H*0.7},{x:rnd(20,W-20),y:H+25}],28)];
    e.d=0;e.fire=ri(30,60);
  }
  pointOnPath(e,seg,e.d);
  if(e.fire--<=0){e.fire=ri(40,90);enemyFire(e);}
}

/* ---------- stage setup ---------- */
function isChallenging(s){return s>=3&&(s-3)%4===0;}
function groupPath(kind){
  let pts=[];
  if(kind==='br')pts=sampleBez([{x:W+16,y:H+16},{x:W-6,y:H-70},{x:W-70,y:H-20},{x:W-46,y:H-78}],24)
      .concat(sampleLoop(W-46,H-78,16,Math.PI/2,Math.PI/2+2*Math.PI,26),
              sampleBez([{x:W-46,y:H-78},{x:W-80,y:H-50},{x:W-70,y:H-95},{x:W-62,y:H-105}],10));
  else if(kind==='bl')pts=sampleBez([{x:-16,y:H+16},{x:6,y:H-70},{x:70,y:H-20},{x:46,y:H-78}],24)
      .concat(sampleLoop(46,H-78,16,-Math.PI/2,-Math.PI/2-2*Math.PI,26),
              sampleBez([{x:46,y:H-78},{x:80,y:H-50},{x:70,y:H-95},{x:62,y:H-105}],10));
  else if(kind==='tr')pts=sampleBez([{x:W+16,y:-16},{x:W-4,y:70},{x:W-70,y:10},{x:W-50,y:70}],24)
      .concat(sampleLoop(W-50,70,15,-Math.PI/2,-Math.PI/2+2*Math.PI,26),
              sampleBez([{x:W-50,y:70},{x:W-80,y:45},{x:W-70,y:85},{x:W-60,y:92}],10));
  else if(kind==='tl')pts=sampleBez([{x:-16,y:-16},{x:4,y:70},{x:70,y:10},{x:50,y:70}],24)
      .concat(sampleLoop(50,70,15,Math.PI*1.5,Math.PI*1.5+2*Math.PI,26),
              sampleBez([{x:50,y:70},{x:80,y:45},{x:70,y:85},{x:60,y:92}],10));
  else if(kind==='mid')pts=sampleLoop(112,64,26,-Math.PI/2,Math.PI*1.5,30);
  return pts;
}
function launchGroup(list,kind,step){
  const pts=groupPath(kind),len=pathLen(pts);
  list.forEach((e,i)=>{e.path=pts;e.len=len;e.d=-i*step;e.delay=0;e.st='entry';e.spd=2.3;});
}
