/* ---------- challenging stage ---------- */
function chalPath(w,side){
  const sgn=side?-1:1;
  const x0=side?W+18:-18,x1=side?-18:W+18;
  const cx=112+sgn*45,cy=90+w*22,r=20+w*4;
  const a0=Math.atan2(0,sgn);
  return sampleBez([{x:x0,y:70+w*16},{x:x0-sgn*40,y:cy-40},{x:cx-sgn*(r+30),y:cy-20},{x:cx+sgn*r,y:cy}],24)
    .concat(sampleLoop(cx,cy,r,a0,a0-sgn*2*Math.PI,26),
            sampleBez([{x:cx+sgn*r,y:cy},{x:cx+sgn*(r+30),y:cy+30},{x:x1-sgn*40,y:cy+60},{x:x1,y:cy+70}],24));
}
function startChallenging(){
  G.enemies=[];G.pshots=[];G.eshots=[];G.fx=[];G.msg=[];
  G.captured=null;FORM.t=0;FORM.ox=0;FORM.oy=0;
  G.player.x=112;G.player.alive=false;G.player.respawn=40;
  const mix=['zako','zako','goei','goei','boss'];
  G.chal={wave:-1,t:120,hits:0,bonus:0,waveKills:0,alive:0,done:false,shown:false};
  for(let w=0;w<5;w++){
    const side=w%2===1;
    const pts=chalPath(w,side),len=pathLen(pts);
    for(let i=0;i<8;i++){
      const e=makeEnemy(mix[w%mix.length],0,9);
      e.st='entry';e.path=pts;e.len=len;e.d=-i*11;e.spd=2.4;e.pts=100;
      G.enemies.push(e);
    }
  }
}
function updateChallenging(){
  const c=G.chal;
  if(c.wave<4&&c.t<=0){c.wave++;c.waveKills=0;c.t=240;sfx.wave();
    addMsg('WAVE '+(c.wave+1),112,140,70,'#00e0ff');}
  else if(c.wave>=0)c.t--;
