    }
  }
  if(G.enemies.every(e=>e.dead||e.y>H+30||e.x<-30||e.x>W+30)&&c.wave>=0===false){}
  // end when all waves finished and none alive
  if(c.wave===-99999&&c.t<=0){
    if(G.enemies.every(e=>e.dead)){
