/* ---------- dive scheduling ---------- */
function pickDiver(){
  const cands=G.enemies.filter(e=>e.st==='formation'&&e.type!=='boss');
  if(!cands.length)return null;
  return cands[ri(0,cands.length-1)];
}
function tryDive(){
  const bosses=G.enemies.filter(e=>e.st==='formation'&&e.type==='boss');
  const goeis=G.enemies.filter(e=>e.st==='formation'&&e.type==='goei');
  // tractor beam attempt (only if no fighter already captured, not first stage)
  if(!G.captured&&bosses.length&&rand()<0.28&&G.stage>=2){
    const b=bosses[ri(0,bosses.length-1)];
    setBeamPath(b);
    if(goeis.length&&rand()<0.5){
      const g=goeis[ri(0,goeis.length-1)];
      b.esc=[g];g.escOf=b;
    }
    return;
  }
  // boss dive with escorts
  if(bosses.length&&rand()<0.3){
    const b=bosses[ri(0,bosses.length-1)];
    setDivePath(b);
    const want=ri(0,2);b.esc=[];
    for(let i=0;i<want&&goeis.length;i++){
      const g=goeis.splice(ri(0,goeis.length-1),1)[0];
      if(g&&g.st==='formation'){b.esc.push(g);g.escOf=b;}
    }
    return;
  }
  const e=pickDiver();
  if(e)setDivePath(e);
}
function updateDives(){
  if(G.banner||G.player.respawn>0)return; // no dives while respawning
  G.diveTimer--;
  if(G.diveTimer<=0){
    const total=G.enemies.filter(e=>e.st==='formation').length;
    const base=Math.max(60,300-18*G.stage-total*3);
    G.diveTimer=ri(base/2,base*1.5);
    if(total>0)tryDive();
  }
}

/* ---------- collisions ---------- */
function rectHit(a,b){return Math.abs(a.x-b.x)*2<a.w+b.w&&Math.abs(a.y-b.y)*2<a.h+b.h;}
function updateBullets(){
  // player shots
  for(const s of G.pshots){
    s.y+=s.vy;
    if(s.y<-8)s.dead=true;
    for(const e of G.enemies){
      if(e.dead||e.st==='entry'&&e.delay>0)continue;
      const ew=e.type==='boss'?13:11,eh=e.type==='boss'?12:10;
      if(rectHit({x:s.x,y:s.y,w:2,h:6},{x:e.x,y:e.y,w:ew,h:eh})){
        s.dead=true;G.shotsHit++;
        if(e.type==='boss'&&e.hp===2){e.hp=1;e.flash=10;sfx.bossHit();}
        else killEnemy(e);
        break;
      }
    }
  }
  // enemy shots vs player
  if(G.player.alive&&!G.banner){
    const boxes=playerHitbox();
    for(const s of G.eshots){
      s.x+=s.vx;s.y+=s.vy;
      if(s.y>H+8||s.x<-8||s.x>W+8){s.dead=true;continue;}
      for(const b of boxes){
        if(rectHit({x:s.x,y:s.y,w:3,h:7},b)){
          s.dead=true;
          if(G.dual&&b.x!==G.player.x){ // outer half hit -> lose partner only
            G.dual=false;sfx.enemyDie();
            G.fx.push({kind:'boom',x:b.x,y:b.y,t:0,big:false});
          }else hitPlayer();
          break;
        }
      }
    }
    // ramming
    for(const e of G.enemies){
      if(e.dead||e.st==='formation'||e.st==='captive'||e.st==='entry'&&e.delay>0)continue;
      for(const b of boxes){
        if(rectHit({x:e.x,y:e.y,w:11,h:10},b)){
          killEnemy(e);hitPlayer();break;
        }
      }
      if(!G.player.alive)break;
    }
  }
  // tractor beam capture
  for(const e of G.enemies){
    if(e.st==='beam'){
      if(G.player.alive&&!G.banner&&G.player.y>H*0.45){
        const f=(G.player.y-e.y)/(H-e.y);
        const hw=4+26*f;
        if(Math.abs(G.player.x-e.x)<hw){capturePlayer(e);beamStop();e.beamT=201;}
      }
    }
  }
}

/* ---------- main update ---------- */
function update(){
  G.frame++;
  updateStars();
  // floating messages
  for(const m of G.msg){m.life--;m.y-=0.15;}
  G.msg=G.msg.filter(m=>m.life>0);
  for(const f of G.fx)f.t++;
  G.fx=G.fx.filter(f=>f.t<(f.big?40:26));

  if(G.mode==='attract'){G.attractT++;return;}

  if(G.banner){
    if(G.frame-G.banner.t0>=G.banner.dur){
      const nb=G.banner.next;G.banner=null;
      if(nb==='nextStage'){G.stage++;startStageBegin();}
      else if(nb==='attract'){G.mode='attract';G.attractT=0;}
    }
    return; // world frozen during banners
  }

  if(G.mode==='stageClear'){
    if(!G.banner){
      G.stage++;
      startStageBegin();
    }
    return;
  }

  updateFormation();
  for(const e of G.enemies){
    if(e.dead)continue;
    if(e.st==='hostile')updateHostile(e);else updateEnemy(e);
  }
  G.enemies=G.enemies.filter(e=>!e.dead);

  updateBullets();
  G.pshots=G.pshots.filter(s=>!s.dead);
  G.eshots=G.eshots.filter(s=>!s.dead);

  // player
  const p=G.player;
  if(p.respawn>0){p.respawn--;if(p.respawn===0){p.alive=true;p.x=112;}}
  if(p.alive){
    const mv=(keys.ArrowLeft||keys.KeyA)?-2:0+(keys.ArrowRight||keys.KeyD)?2:0;
    p.x=clamp(p.x+((keys.ArrowLeft||keys.KeyA)?-2:0)+((keys.ArrowRight||keys.KeyD)?2:0),12,W-12-(G.dual?14:0));
    if(p.shotCd>0)p.shotCd--;
    if(keys.Space&&p.shotCd===0)firePlayer();
  }

  if(G.mode==='challenging'){updateChallenging();return;}

  updateDives();

  // stage cleared?
  if(G.enemies.length===0){
    G.banner={t:'STAGE '+G.stage+' CLEAR',t0:G.frame,dur:150,next:'nextStage'};
    sfx.jingle();
  }
}
function startStageBegin(){
  if(isChallenging(G.stage)){
    startChallenging();G.mode='challenging';
    G.banner={t:'CHALLENGING STAGE',t0:G.frame,dur:140,next:null};
  }else{
    startStage();G.mode='play';
    G.banner={t:'STAGE '+G.stage,t0:G.frame,dur:110,next:null};
  }
  sfx.jingle();
}
