/* ---------- rendering ---------- */
function txt(s,x,y,col,size,align){
  ctx.fillStyle=col;ctx.font='bold '+(size||8)+'px monospace';
  ctx.textAlign=align||'left';ctx.fillText(s,x,y);ctx.textAlign='left';
}
function drawSprite(img,x,y,ang,flip){
  if(!ang&&!flip){ctx.drawImage(img,(x-img.width/2)|0,(y-img.height/2)|0);return;}
  ctx.save();ctx.translate(x|0,y|0);
  if(ang)ctx.rotate(ang);if(flip)ctx.scale(-1,1);
  ctx.drawImage(img,-(img.width/2)|0,-(img.height/2)|0);
  ctx.restore();
}
function enemySprite(e){
  if(e.type==='captured')return SPR.captured;
  if(e.type==='zako')return e.flap?SPR.zako2:SPR.zako1;
  if(e.type==='goei')return e.flap?SPR.goei2:SPR.goei1;
  return e.hp===2?SPR.boss1:SPR.boss2;
}
function drawEnemy(e){
  if(e.delay>0&&e.st==='entry')return;
  const ang=(e.st==='dive'||e.st==='escort'||e.st==='hostile'||e.st==='beam'||e.st==='entry'||e.st==='toSlot')
    ?e.ang-Math.PI/2:0;
  if(e.flash){ctx.save();ctx.globalAlpha=0.6;ctx.fillStyle='#fff';
    ctx.fillRect(e.x-8,e.y-8,16,16);ctx.restore();}
  drawSprite(enemySprite(e),e.x,e.y,ang,e.dir<0);
}
function drawBeam(e){
  const bot=H,y0=e.y+6,f=(bot-y0);
  const t=G.frame*0.25;
  for(let i=0;i<8;i++){
    const yy=y0+f*i/8,y2=y0+f*(i+1)/8;
    const w1=4+26*(i/8),w2=4+26*((i+1)/8);
    ctx.fillStyle=(i+((t|0)))%2?'#3050ff':'#80c0ff';
    ctx.beginPath();
    ctx.moveTo(e.x-w1,yy);ctx.lineTo(e.x+w1,yy);
    ctx.lineTo(e.x+w2,y2);ctx.lineTo(e.x-w2,y2);
    ctx.closePath();ctx.fill();
  }
}
function drawExplosion(f){
  const t=f.t,max=f.big?40:26,p=t/max;
  const r=2+p*(f.big?18:12);
  const col=p<0.35?'#ffffff':p<0.6?'#ffd820':'#ff3030';
  ctx.strokeStyle=col;ctx.lineWidth=1;
  ctx.beginPath();ctx.arc(f.x,f.y,r,0,Math.PI*2);ctx.stroke();
  for(let i=0;i<8;i++){
    const a=i*Math.PI/4+p*1.5;
    ctx.beginPath();
    ctx.moveTo(f.x+Math.cos(a)*(r*0.4),f.y+Math.sin(a)*(r*0.4));
    ctx.lineTo(f.x+Math.cos(a)*(r+3),f.y+Math.sin(a)*(r+3));
    ctx.stroke();
  }
  if(f.big&&t<24){ // player debris flashes
    ctx.fillStyle=t%4<2?'#fff':'#2a7bff';
    for(let i=0;i<5;i++){const a=i*1.3+t*0.2;
      ctx.fillRect((f.x+Math.cos(a)*(r+4))|0,(f.y+Math.sin(a)*(r+4))|0,2,2);}
  }
}
