  for(const f of G.fx)drawExplosion(f);

  // player
  const p=G.player;
  if(p.alive){
    const blink=p.respawn===0&&G.frame<30&&G.frame%4<2;
    if(!blink){
      drawSprite(SPR.player,p.x,H-24,0,false);
      if(G.dual)drawSprite(SPR.player,p.x+14,H-24,0,false);
    }
  }

  // messages
  for(const m of G.msg)txt(m.t,m.x,m.y,m.col,7,'center');

  drawHUD();

  // banners
  if(G.banner){
    const b=G.banner;
    if(b.t)txt(b.t,112,140,'#00e0ff',12,'center');
    if(b.extra)txt(b.extra,112,158,'#ffd820',9,'center');
    if(!b.t)txt('READY',112,140,'#ff4040',12,'center');
  }else if(G.player.respawn>0&&G.mode!=='gameover'&&G.mode!=='results'){
    txt('READY',112,140,'#ff4040',12,'center');
  }
  if(G.mode==='results'){
    const r=Math.round(G.shotsFired?100*G.shotsHit/G.shotsFired:0);
    txt('SHOTS FIRED = '+G.shotsFired,112,110,'#ffffff',9,'center');
    txt('NUMBER OF HITS = '+G.shotsHit,112,126,'#ffffff',9,'center');
    txt('HIT-MISS RATIO = '+r+'%',112,142,'#ffffff',9,'center');
    if(G.frame%60<40)txt('PRESS ENTER TO PLAY AGAIN',112,170,'#ffd820',8,'center');
  }
  if(G.paused)txt('PAUSED',112,150,'#ffd820',10,'center');
}

/* ---------- fixed-timestep loop ---------- */
let acc=0,last=performance.now();
function loop(now){
  requestAnimationFrame(loop);
  acc+=Math.min(100,now-last);last=now;
  const STEP=1000/60;
  while(acc>=STEP){
    if(!G.paused)update();
    acc-=STEP;
  }
  render();
}
requestAnimationFrame(loop);
</script>
</body>
</html>
```

Notes on things from the spec I did not fully implement:

- **Enemy rotation fidelity during entry/dives**: divers rotate to their travel direction, but the arcade's precise per-group entry choreography (exact loop shapes and the way bees enter from the bottom corners in two file lines) is approximated with generated loop paths rather than the original point data.
- **Boss dive scoring nuance**: escort count is taken from escorts still alive at the moment the boss dies; escorts that were killed earlier reduce the bonus (800 → 400), which matches the arcade, but escorts never peel off independently as they sometimes do in the original.
- **Captured-fighter hostile behaviour**: when its boss is shot in formation, the captive turns hostile and dives repeatedly, but it does not take over the boss's formation slot.
- **Challenging-stage wave composition** is a fixed mix (bees/butterflies/bosses) rather than the arcade's exact per-wave line-ups; challenging bosses still take two hits.
- Minor arcade details omitted: the "FIGHTERS CAPTURED" attract demo sequence, coin/credit handling, and the attract-mode high-score initials entry.
